<?php
// Standalone demo-data reset. No login or application includes required.
$cli = PHP_SAPI === 'cli';
if (!$cli) {
    session_start();
    header('Cache-Control: no-store');
    if (!isset($_SESSION['reset_token'])) { $_SESSION['reset_token'] = bin2hex(random_bytes(32)); }
}
function stopPage($message, $status = 400) {
    if (PHP_SAPI !== 'cli') { http_response_code($status); }
    echo htmlspecialchars($message, ENT_QUOTES, 'UTF-8') . PHP_EOL;
    exit(1);
}
$baseline = json_decode(base64_decode(''), true);
$done = false;

// Write into the existing file so PHP ownership does not change.
function restoreFileContents($file, $text) {
    if (!rewind($file)) { return false; }
    $written = 0;
    while ($written < strlen($text)) {
        $amount = @fwrite($file, substr($text, $written));
        if ($amount === false || $amount === 0) { return false; }
        $written += $amount;
    }
    if (!@ftruncate($file, strlen($text)) || !fflush($file) || !rewind($file)) { return false; }
    return stream_get_contents($file) === $text;
}

if ($cli || $_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!$cli && (!hash_equals($_SESSION['reset_token'], (string) ($_POST['token'] ?? '')) || ($_POST['reset'] ?? '') !== 'yes')) { stopPage('Invalid reset request.', 403); }
    $files = []; $before = [];
    // Open and read every target before changing any file.
    foreach ($baseline as $name => $text) {
        $file = @fopen(__DIR__ . '/' . $name, 'r+b');
        if ($file === false) {
            foreach ($files as $open) { fclose($open); }
            stopPage('PHP cannot write to ' . $name . '. Nothing was reset. The file must already exist and be writable by PHP.', 503);
        }
        $files[$name] = $file;
        $before[$name] = stream_get_contents($file);
        if ($before[$name] === false) {
            foreach ($files as $open) { fclose($open); }
            stopPage('Could not read the current data. Nothing was reset.', 503);
        }
    }
    $failed = false;
    foreach ($baseline as $name => $text) {
        if (!restoreFileContents($files[$name], $text)) { $failed = true; break; }
    }
    if ($failed) {
        $rolledBack = true;
        foreach ($before as $name => $text) {
            if (!restoreFileContents($files[$name], $text)) { $rolledBack = false; }
        }
        foreach ($files as $open) { fclose($open); }
        stopPage($rolledBack ? 'Reset failed. The previous data was restored.' : 'Reset failed and the previous data could not be fully restored. Restore your backup before continuing.', 503);
    }
    foreach ($files as $open) { fclose($open); }
    $done = true;
}
if ($cli) { echo "Demo data reset to the saved snapshot." . PHP_EOL; exit; }
?>
<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Reset ProKnow demo</title><link rel="stylesheet" href="styles.css"></head>
<body><div class="container"><section class="info narrow">
<h1>Reset Demo</h1>
<?php if ($done): ?>
<p role="status">Done</p>
<a href="./index.php">Home</a>
<?php else: ?>
<form method="post" onsubmit="return confirm('Reset all demo data to the saved snapshot?')">
<input type="hidden" name="token" value="<?= htmlspecialchars($_SESSION['reset_token'], ENT_QUOTES, 'UTF-8') ?>">
<input type="hidden" name="reset" value="yes">
<button type="submit">Reset data</button>
</form>
<?php endif; ?>
</section></div></body></html>
